#!/usr/bin/env python3
"""Generate the hero server-rack SVG for index.html.

    python3 scripts/make-rack.py > rack.svg

Paste the output into the hero in index.html, replacing the block between
<!-- rack: generated by scripts/make-rack.py --> and <!-- /rack -->.

Standard library only. The markup carries geometry and class names, no colours:
every colour and opacity is set in index.html's CSS from the theme variables.
Every line and rect gets pathLength="1" so the CSS draw-in can animate
stroke-dashoffset from 1 to 0.
"""

# Canvas the rack is drawn on (matches the 1280x820 design reference).
VIEW_W, VIEW_H = 1280, 820

UNITS = 16             # rack height in U
U = 44                 # px per unit
TOP = 88               # y of the top of the highest unit
RAIL_X = (760, 1206)   # x of the outer edge of the left / right rail pair
RAIL_GAP = 14          # distance between the two rails of a pair
RAIL_OVERHANG = 20     # rails run past the first and last unit by this much

DEV_X = RAIL_X[0] + RAIL_GAP + 4            # 778: devices sit just inside the rails
DEV_W = RAIL_X[1] - 4 - DEV_X               # 424
DEV_INSET = 3                               # gap above/below each faceplate
LABEL_X = RAIL_X[0] - 10                    # unit numbers, right-aligned

# Devices, top to bottom. "slot" counts from the TOP of the rack (slot 1 is the
# highest unit), as in the brief; the printed unit labels follow the usual rack
# convention instead (16 at the top, 01 at the bottom).
DEVICES = [
    # (first slot, height in U, kind)
    (1, 2, "server"),
    (3, 1, "switch"),
    (5, 1, "server"),
    (6, 4, "storage"),
    (11, 1, "attention"),
    (12, 2, "server"),
]


def f(n):
    """Compact number formatting: 125.0 -> 125, 2.5 -> 2.5."""
    return f"{n:g}"


def line(x1, y1, x2, y2):
    return f'<line pathLength="1" x1="{f(x1)}" y1="{f(y1)}" x2="{f(x2)}" y2="{f(y2)}"/>'


def rect(x, y, w, h, rx):
    return f'<rect pathLength="1" x="{f(x)}" y="{f(y)}" width="{f(w)}" height="{f(h)}" rx="{f(rx)}"/>'


def frame():
    y0, y1 = TOP - RAIL_OVERHANG, TOP + UNITS * U + RAIL_OVERHANG
    out = []
    for x in RAIL_X:
        out += [line(x, y0, x, y1), line(x + RAIL_GAP, y0, x + RAIL_GAP, y1)]
    for i in range(UNITS + 1):          # a tick at every unit boundary, both rail pairs
        y = TOP + i * U
        for x in RAIL_X:
            out.append(line(x, y, x + RAIL_GAP, y))
    return out


def labels():
    out = []
    for i in range(UNITS):
        y = TOP + i * U + 26             # baseline, roughly centred in the unit
        out.append(f'<text x="{LABEL_X}" y="{y}" text-anchor="end">{UNITS - i:02d}</text>')
    return out


def device(slot, height, kind):
    y = TOP + (slot - 1) * U + DEV_INSET
    h = height * U - 2 * DEV_INSET
    cy = y + h / 2
    out = [rect(DEV_X, y, DEV_W, h, 3)]
    # four short vent slots on the left of every device
    out += [line(DEV_X + 16 + 8 * k, cy - 7, DEV_X + 16 + 8 * k, cy + 7) for k in range(4)]
    if kind in ("server", "attention"):
        out.append(line(DEV_X + 90, cy, DEV_X + 334, cy))               # one thin detail line
    elif kind == "switch":
        out += [rect(DEV_X + 90 + 22 * k, cy - 6, 16, 12, 1.5) for k in range(12)]
    elif kind == "storage":
        bay_h = (h - 48) / 2                                            # two rows of six bays
        for row in range(2):
            by = y + 18 + row * (bay_h + 18)
            out += [rect(DEV_X + 80 + 52 * k, by, 44, bay_h, 2) for k in range(6)]
    return out, cy


def main():
    devices, attention = [], []
    bar_y = None
    for slot, height, kind in DEVICES:
        parts, cy = device(slot, height, kind)
        if kind == "attention":
            attention += parts
            bar_y = cy
        else:
            devices += parts
    bar_x1 = DEV_X + DEV_W - 20
    bar = line(bar_x1 - 44, bar_y, bar_x1, bar_y)                       # 44px status bar

    def g(cls, items):
        return f'<g class="{cls}">' + "".join(items) + "</g>"

    print(
        f'<svg class="rack" aria-hidden="true" focusable="false" viewBox="0 0 {VIEW_W} {VIEW_H}" '
        'preserveAspectRatio="xMaxYMid meet">'
        '<g class="rk-dim">'
        + g("rk-frame rk-draw", frame())
        + g("rk-labels rk-fade", labels())
        + g("rk-dev rk-draw", devices)
        + g("rk-att rk-draw", attention)
        + "</g>"
        + g("rk-bar rk-fade", [g("rk-pulse", [bar])])
        + "</svg>"
    )


if __name__ == "__main__":
    main()
